#!/usr/bin/env python3
"""
Comprehensive test to verify the fix works correctly and doesn't break existing functionality
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from msal.application import ClientApplication


def test_non_b2c_authority():
    """Test that non-B2C authorities still work as before"""
    print("=== Testing Non-B2C Authority (Regular Azure AD) ===")

    # Create client application with regular authority behavior
    client_id = "test-client-id-12345"
    app = ClientApplication(client_id=client_id)

    # Manually set the authority properties for testing (non-B2C)
    app.authority = type('MockAuthority', (), {
        '_is_b2c': False,
        'is_adfs': False
    })()

    print(f"Non-B2C authority detected: {getattr(app.authority, '_is_b2c', False)}")

    # Test 1: Standard scopes should work
    try:
        result = app._decorate_scope(["https://api.example.com/read"])
        print(f"✓ Standard scopes: {sorted(result)}")
    except Exception as e:
        print(f"✗ Standard scopes failed: {e}")

    # Test 2: Client ID with other scopes should FAIL for non-B2C (preserve existing behavior)
    try:
        result = app._decorate_scope([client_id, "openid"])
        print(f"✗ UNEXPECTED: Client ID + other scopes succeeded: {sorted(result)}")
    except ValueError as e:
        print(f"✓ EXPECTED: Client ID + other scopes correctly rejected: {e}")

    # Test 3: Single client ID should work and get replaced with standard scopes
    try:
        result = app._decorate_scope([client_id])
        expected = ['offline_access', 'openid', 'profile']
        if sorted(result) == expected:
            print(f"✓ Single client ID correctly becomes standard scopes: {sorted(result)}")
        else:
            print(f"✗ Single client ID incorrect result: {sorted(result)}, expected: {expected}")
    except Exception as e:
        print(f"✗ Single client ID failed: {e}")

    # Test 4: Reserved scopes alone should fail for non-B2C (preserve existing behavior)
    try:
        result = app._decorate_scope(["openid"])
        print(f"✗ UNEXPECTED: Reserved scope alone succeeded: {sorted(result)}")
    except ValueError as e:
        print(f"✓ EXPECTED: Reserved scope alone correctly rejected: {e}")


def test_b2c_authority():
    """Test that B2C authorities work with the new behavior"""
    print("\n=== Testing B2C Authority ===")

    # Create client application with B2C authority behavior
    client_id = "test-b2c-client-id-67890"
    app = ClientApplication(client_id=client_id)

    # Manually set the authority properties for testing (B2C)
    app.authority = type('MockAuthority', (), {
        '_is_b2c': True,
        'is_adfs': False
    })()

    print(f"B2C authority detected: {getattr(app.authority, '_is_b2c', False)}")

    # Test 1: Standard scopes should work
    try:
        result = app._decorate_scope(["https://api.example.com/read"])
        print(f"✓ Standard scopes: {sorted(result)}")
    except Exception as e:
        print(f"✗ Standard scopes failed: {e}")

    # Test 2: Client ID with other scopes should WORK for B2C (new behavior)
    try:
        result = app._decorate_scope([client_id, "openid", "offline_access"])
        expected_elements = ['offline_access', 'openid', 'profile', client_id]
        if all(elem in result for elem in expected_elements) and len(result) == len(expected_elements):
            print(f"✓ B2C: Client ID + other scopes correctly preserved: {sorted(result)}")
        else:
            print(f"✗ B2C: Client ID + other scopes incorrect: {sorted(result)}")
    except Exception as e:
        print(f"✗ B2C: Client ID + other scopes failed: {e}")

    # Test 3: Single client ID should work and include client_id in result
    try:
        result = app._decorate_scope([client_id])
        if client_id in result and 'openid' in result and 'offline_access' in result:
            print(f"✓ B2C: Single client ID correctly decorated: {sorted(result)}")
        else:
            print(f"✗ B2C: Single client ID incorrect result: {sorted(result)}")
    except Exception as e:
        print(f"✗ B2C: Single client ID failed: {e}")

    # Test 4: Reserved scopes with client_id should work for B2C
    try:
        result = app._decorate_scope(["openid", client_id])
        if 'openid' in result and client_id in result:
            print(f"✓ B2C: Reserved scope + client_id works: {sorted(result)}")
        else:
            print(f"✗ B2C: Reserved scope + client_id failed: {sorted(result)}")
    except Exception as e:
        print(f"✗ B2C: Reserved scope + client_id error: {e}")


def test_edge_cases():
    """Test edge cases and error conditions"""
    print("\n=== Testing Edge Cases ===")

    client_id = "test-edge-client-id-11111"
    app = ClientApplication(client_id=client_id)

    # Test with authority that doesn't have _is_b2c attribute
    app.authority = type('MockAuthority', (), {})()  # No _is_b2c attribute

    # Should behave like non-B2C (default False)
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ Missing _is_b2c attribute handled correctly: {sorted(result)}")
    except Exception as e:
        print(f"✗ Missing _is_b2c attribute error: {e}")

    # Test with None authority (should not crash)
    app.authority = None
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ None authority handled gracefully: {sorted(result)}")
    except AttributeError as e:
        print(f"✓ Expected AttributeError with None authority: {e}")
    except Exception as e:
        print(f"✗ Unexpected error with None authority: {e}")


if __name__ == "__main__":
    test_non_b2c_authority()
    test_b2c_authority()
    test_edge_cases()
